// <auto-generated/>

namespace Fanex.CustomerSetting.Module.SearchCopy.Controllers
{
    using System;
    using System.Linq;
    using System.Web.Mvc;
    using System.Web.SessionState;
    using App_Start;
    using Common;
    using Core.Models;
    using Core.Web;
    using Core.Web.Controllers;
    using Criteria;
    using Logging.Extensions.Web;
    using NAP.Framework.Data;
    using Services;
    using Sunplus.Accounting.Core.Configurations;
    using ViewModels;

    [SessionState(SessionStateBehavior.ReadOnly)]
    public class SuperController : BaseController
    {
        private readonly ISearchCopyService _searchCopyService;

        public SuperController()
            : this(null)
        {
        }

        internal SuperController(ISearchCopyService searchCopyService)
        {
            _searchCopyService = searchCopyService ?? new SearchCopyService();
        }

        public ActionResult Index()
            => View("~/Areas/CustomerSetting/Views/SearchCopy/Super/Index.cshtml");

        public ActionResult SearchExistingSuper(string username, string level = "member")
        {
            var result = _searchCopyService.SearchExistingCustomer(username, IsMember(level));

            return Json(
                new CustomerSettingView(result.CustId, username, result.ParentId, result.BreadCrumbs),
                JsonRequestBehavior.AllowGet);
        }

        public ActionResult GetCustomerInfoByUserId(int custid, string level = "member")
        {
            var custInfo = _searchCopyService.GetCustomerInfoByUserId(custid, IsMember(level), WebSettings.SettingStatus);

            return Json(custInfo, JsonRequestBehavior.AllowGet);
        }

        public ActionResult GetSites()
        {
            var sites = _searchCopyService.GetSitesExistingSuper(AppSession.AccId);

            return Json(sites, JsonRequestBehavior.AllowGet);
        }


        public ActionResult MultipleAccounts(MultipleAccountsViewModel viewModel)
        {
            var isMember = viewModel.ParentId > 0;
            viewModel.Customer = _searchCopyService.GetCustomerInfoByUserId(viewModel.CustId, isMember, WebSettings.SettingStatus);
            if (viewModel.Customer.RoleId == 4)
            {
                viewModel.Sites = _searchCopyService
                    .GetSitesExistingSuper(AppSession.AccId);
            }

            return View("~/Areas/CustomerSetting/Views/SearchCopy/Super/MultipleAccounts.cshtml", viewModel);
        }

        [HttpPost]
        public ActionResult CheckAvailableUsernames(int custId, int parentId, string usernames)
            => Json(_searchCopyService.CheckAvailableUsernames(usernames), JsonRequestBehavior.DenyGet);

        protected override void OnActionExecuting(ActionExecutingContext filterContext)
        {
            ViewBag.RootUrl = $"{Url.Content("~")}{filterContext.RouteData.DataTokens["area"].ToString()}/{ModuleRegistrator.Module}/";

            base.OnActionExecuting(filterContext);
        }

        private static bool IsMember(string level)
            => level.Equals("member", StringComparison.OrdinalIgnoreCase);
    }
}
